try {
  SetupCommandUpdateHandlers();
  await ComposeStartup();
} catch (ex) {
  console.error(ex);
  Services.prompt.alert(
    window,
    getComposeBundle().getString("initErrorDlogTitle"),
    getComposeBundle().getString("initErrorDlgMessage")
  );

  MsgComposeCloseWindow();
  return;
}
